namespace sv_396d921b81564642b588c4b8defe28a0.Services;

/// <summary>
/// Holds the currently selected warehouse for a single circuit (user session).
/// Registered as Scoped so each Blazor Server circuit gets its own instance.
/// </summary>
public sealed class WarehouseStateService
{
    public static readonly IReadOnlyList<(string Id, string Name)> AvailableWarehouses =
    [
        ("WH-A", "Warehouse A"),
        ("WH-B", "Warehouse B"),
        ("WH-C", "Warehouse C"),
    ];

    private string _currentWarehouseId = AvailableWarehouses[0].Id;

    public string CurrentWarehouseId => _currentWarehouseId;

    public string CurrentWarehouseName =>
        AvailableWarehouses.FirstOrDefault(w => w.Id == _currentWarehouseId).Name
        ?? _currentWarehouseId;

    public event Func<Task>? OnChange;

    public async Task SetWarehouseAsync(string warehouseId)
    {
        if (_currentWarehouseId == warehouseId)
            return;

        _currentWarehouseId = warehouseId;

        if (OnChange is not null)
            await OnChange.Invoke();
    }
}

namespace sv_396d921b81564642b588c4b8defe28a0.Services;

/// <summary>
/// Polls for low-stock alerts on a 10-second interval.
/// Scoped per circuit so each user has independent alert counts.
/// Polling is reference-counted: starts when the first subscriber calls
/// StartPollingAsync and stops when the last one calls StopPolling.
/// </summary>
public sealed class InventoryAlertService : IDisposable
{
    private readonly WarehouseStateService _warehouseState;
    private readonly Random _random = new();

    private CancellationTokenSource? _cts;
    private int _subscriberCount;
    private int _lastAlertCount;

    public int CurrentAlertCount => _lastAlertCount;

    /// <summary>
    /// Raised on the calling (Blazor synchronization) context whenever new
    /// alert data arrives. Every subscribed component receives the notification.
    /// </summary>
    public event Func<Task>? OnAlertCountChanged;

    public InventoryAlertService(WarehouseStateService warehouseState)
    {
        _warehouseState = warehouseState;
    }

    /// <summary>
    /// Simulates a database query returning a random low-stock count.
    /// </summary>
    public Task<int> GetLowStockCountAsync(string warehouseId)
    {
        return Task.FromResult(_random.Next(0, 16));
    }

    /// <summary>
    /// Begin polling. Safe to call multiple times – only the first call
    /// starts the background loop.
    /// </summary>
    public async Task StartPollingAsync()
    {
        _subscriberCount++;

        if (_subscriberCount == 1)
        {
            _cts = new CancellationTokenSource();
            // Fetch immediately so the UI has data right away.
            await RefreshAsync();
            _ = PollLoopAsync(_cts.Token);
        }
    }

    /// <summary>
    /// Decrement subscribers. When the last one leaves, the loop is cancelled.
    /// </summary>
    public void StopPolling()
    {
        _subscriberCount = Math.Max(0, _subscriberCount - 1);

        if (_subscriberCount == 0)
        {
            _cts?.Cancel();
            _cts?.Dispose();
            _cts = null;
        }
    }

    /// <summary>
    /// Force an immediate refresh (e.g. after a warehouse change).
    /// </summary>
    public async Task RefreshAsync()
    {
        _lastAlertCount = await GetLowStockCountAsync(_warehouseState.CurrentWarehouseId);

        if (OnAlertCountChanged is not null)
            await OnAlertCountChanged.Invoke();
    }

    private async Task PollLoopAsync(CancellationToken ct)
    {
        using var timer = new PeriodicTimer(TimeSpan.FromSeconds(10));

        try
        {
            while (await timer.WaitForNextTickAsync(ct))
            {
                await RefreshAsync();
            }
        }
        catch (OperationCanceledException)
        {
            // Expected when polling is stopped.
        }
    }

    public void Dispose()
    {
        _cts?.Cancel();
        _cts?.Dispose();
    }
}

