        // Also refresh alerts immediately for the new warehouse.
        await AlertService.RefreshAsync();
    }

    private async Task HandleStateChanged()
    {
        await InvokeAsync(StateHasChanged);
    }

    public void Dispose()
    {
        WarehouseState.OnChange -= HandleStateChanged;
    }
}

